SELECT id, package_id, api_code, cell, source_type
FROM b_didi_v5_colliding_data_rob
WHERE push_time is null
  AND is_delete = 0
  AND colliding_time < #{startTime}
  AND id > #{maxId}
ORDER BY id asc
    LIMIT #{limit}

SELECT id, package_id, api_code, cell, source_type
FROM b_didi_v5_colliding_data_rob
WHERE push_time is null
  AND is_delete = 0
  AND colliding_time BETWEEN #{startTime} AND #{endTime}
  AND id > #{maxId}
ORDER BY id asc
    LIMIT #{limit}

